<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var isCurrent = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isFuture = !isCurrent && !isCompleted;

        <div class="step @(isCurrent ? "step--current" : "") @(isCompleted ? "step--completed" : "") @(isFuture ? "step--future" : "")">
            @if (isCompleted)
            {
                <button class="step__button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                    <span class="step__icon">&#10003;</span>
                    <span class="step__label">@StepNames[step]</span>
                </button>
            }
            else
            {
                <span class="step__marker">@(step + 1)</span>
                <span class="step__label">@StepNames[step]</span>
            }
        </div>

        @if (i < StepNames.Count - 1)
        {
            <div class="step__connector @(isCompleted ? "step__connector--completed" : "")"></div>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };
}

