{"file_text": "@namespace sv_a8fd67d5aa1649c4b87fec579e6c5d5c.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="alert alert--success">
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert--error">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-section__header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn--link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h4>Work History</h4>
                <button type="button" class="btn btn--link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h4>References</h4>
                <button type="button" class="btn btn--link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-item">
                    <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email @(!string.IsNullOrEmpty(r.Phone) ? $"/ {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn--link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        <div class="step-actions">
            <button type="button" class="btn btn--outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn--primary btn--lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    public bool IsSubmitted { get; set; }
    public int ApplicationId { get; set; }
    public bool IsSubmitting { get; set; }
    public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        await OnSubmit.InvokeAsync();
    }

    public void SetSubmitted(int applicationId)
    {
        IsSubmitted = true;
        ApplicationId = applicationId;
        IsSubmitting = false;
        StateHasChanged();
    }

    public void SetError(string error)
    {
        ErrorMessage = error;
        IsSubmitting = false;
        StateHasChanged();
    }
}
", "path": "/tmp/sv-a8fd67d5aa1649c4b87fec579e6c5d5c/Components/Pages/Apply/ReviewStep.razor"}

