@namespace sv_a8fd67d5aa1649c4b87fec579e6c5d5c.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert--error">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 2)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    @if (Entries.Count < 3)
    {
        <button type="button" class="btn btn--secondary" @onclick="AddEntry">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn btn--outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn--primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        if (Entries.Count < 3)
            Entries.Add(new ReferenceModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 2)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, ReferenceModel updated)
    {
        Entries[index] = updated;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) || string.IsNullOrWhiteSpace(entry.Relationship) ||
                string.IsNullOrWhiteSpace(entry.Email))
            {
                ErrorMessage = "Each reference must have a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

