@page "/apply"
@using sv_a8fd67d5aa1649c4b87fec579e6c5d5c.Models
@using sv_a8fd67d5aa1649c4b87fec579e6c5d5c.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              OnNext="HandlePersonalNext" ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep Entries="@references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep @ref="reviewStepRef"
                        FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="@workEntries" References="@references" CoverLetter="@coverLetter"
                        OnBack="GoBack" OnEditSection="GoToStep" OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();
    private ReviewStep? reviewStepRef;

    // Step 1 data
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2 data
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 data
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 data
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> entries)
    {
        references = entries;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        try
        {
            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            completedSteps.Add(4);
            reviewStepRef?.SetSubmitted(id);
        }
        catch (Exception ex)
        {
            reviewStepRef?.SetError($"Submission failed: {ex.Message}");
        }
    }
}

.apply-page {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.step__marker {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    font-weight: 600;
    background: #e2e8f0;
    color: #94a3b8;
}

.step--current .step__marker {
    background: #3b82f6;
    color: #fff;
}

.step__icon {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    background: #10b981;
    color: #fff;
}

.step__button {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
}

.step__button:hover .step__label {
    text-decoration: underline;
}

.step__label {
    font-size: 0.8rem;
    color: #334155;
    white-space: nowrap;
}

.step--future .step__label {
    color: #94a3b8;
}

.step--current .step__label {
    font-weight: 600;
    color: #3b82f6;
}

.step__connector {
    width: 1.5rem;
    height: 2px;
    background: #e2e8f0;
    margin: 0 0.25rem;
}

.step__connector--completed {
    background: #10b981;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-content h3 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1e293b;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #475569;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    box-sizing: border-box;
