.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.4rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.char-count {
    display: block;
    margin-top: 0.3rem;
    font-size: 0.8rem;
    color: #64748b;
}

.field-error {
    color: #ef4444;
    font-size: 0.8rem;
    margin-top: 0.2rem;
    display: block;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.15s;
}

.btn--primary {
    background: #3b82f6;
    color: #fff;
}

.btn--primary:hover {
    background: #2563eb;
}

.btn--primary:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn--outline {
    background: #fff;
    color: #3b82f6;
    border-color: #3b82f6;
}

.btn--outline:hover {
    background: #eff6ff;
}

.btn--secondary {
    background: #f1f5f9;
    color: #475569;
    border-color: #cbd5e1;
}

.btn--secondary:hover {
    background: #e2e8f0;
}

.btn--danger {
    background: #fee2e2;
    color: #dc2626;
    border-color: #fecaca;
}

.btn--danger:hover {
    background: #fecaca;
}

.btn--sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

.btn--lg {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

.btn--link {
    background: none;
    border: none;
    color: #3b82f6;
    padding: 0;
    font-size: 0.85rem;
    cursor: pointer;
    text-decoration: underline;
}

/* Step Actions */
.step-actions {
    display: flex;
    gap: 0.75rem;
