    padding-top: 1rem;
    border-top: 1px solid #e2e8f0;
}

/* Alerts */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
}

.alert--error {
    background: #fef2f2;
    color: #dc2626;
    border: 1px solid #fecaca;
}

.alert--success {
    background: #f0fdf4;
    color: #166534;
    border: 1px solid #bbf7d0;
}

/* Work Entry / Reference Entry */
.work-entry,
.reference-entry {
    border: 1px solid #e2e8f0;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry__header,
.reference-entry__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry__header h4,
.reference-entry__header h4 {
    margin: 0;
    font-size: 0.95rem;
    color: #334155;
}

/* Review Section */
.review-section {
    border: 1px solid #e2e8f0;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section__header h4 {
    margin: 0;
    color: #1e293b;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #64748b;
    font-size: 0.85rem;
}

.review-section dd {
    margin: 0;
    color: #1e293b;
}

.review-item {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f1f5f9;
}

.review-item:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #334155;
    font-size: 0.9rem;
}

