.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #475569;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.4rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.char-count {
    display: block;
    margin-top: 0.3rem;
    font-size: 0.8rem;
    color: #64748b;
}

.field-error {
    color: #ef4444;
    font-size: 0.8rem;
    margin-top: 0.2rem;
    display: block;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.15s;
}

.btn--primary {
    background: #3b82f6;
    color: #fff;
}

.btn--primary:hover {
    background: #2563eb;
}

.btn--primary:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn--outline {
    background: #fff;
    color: #3b82f6;
    border-color: #3b82f6;
}

.btn--outline:hover {
    background: #eff6ff;
}

.btn--secondary {
    background: #f1f5f9;
    color: #475569;
    border-color: #cbd5e1;
}

.btn--secondary:hover {
    background: #e2e8f0;
}

.btn--danger {
    background: #fee2e2;
    color: #dc2626;
    border-color: #fecaca;
}

.btn--danger:hover {
    background: #fecaca;
}

.btn--sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

.btn--lg {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

.btn--link {
    background: none;
    border: none;
    color: #3b82f6;
    padding: 0;
    font-size: 0.85rem;
    cursor: pointer;
    text-decoration: underline;
}

/* Step Actions */
.step-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e2e8f0;
}

/* Alerts */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
}

.alert--error {
    background: #fef2f2;
    color: #dc2626;
    border: 1px solid #fecaca;
}

.alert--success {
    background: #f0fdf4;
    color: #166534;
    border: 1px solid #bbf7d0;
}

/* Work Entry / Reference Entry */
.work-entry,
.reference-entry {
    border: 1px solid #e2e8f0;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry__header,
.reference-entry__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry__header h4,
.reference-entry__header h4 {
    margin: 0;
    font-size: 0.95rem;
    color: #334155;
}

/* Review Section */
.review-section {
    border: 1px solid #e2e8f0;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section__header h4 {
    margin: 0;
    color: #1e293b;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #64748b;
    font-size: 0.85rem;
}

.review-section dd {
    margin: 0;
    color: #1e293b;
}

.review-item {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f1f5f9;
}

.review-item:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #334155;
    font-size: 0.9rem;
}
