@namespace sv_a8fd67d5aa1649c4b87fec579e6c5d5c.Components.Pages.Apply

<div class="work-entry">
    <div class="work-entry__header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn--danger btn--sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="HandleCompanyChange" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="HandleTitleChange" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(Entry.StartDate)"
                   @onchange="HandleStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatNullableDate(Entry.EndDate)" disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="HandleCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="HandleDescriptionChange"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;

    private void UpdateEntry(WorkEntryModel updated) => OnEntryChanged.InvokeAsync(updated);

    private void HandleCompanyChange(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty });

    private void HandleTitleChange(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty });

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        if (!string.IsNullOrEmpty(val) && DateTime.TryParse(val, out var date))
            UpdateEntry(Entry with { StartDate = date });
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        UpdateEntry(Entry with { EndDate = endDate });
    }

    private void HandleCurrentChange(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        UpdateEntry(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    private void HandleDescriptionChange(ChangeEventArgs e) =>
        UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty });
}

